<script nonce="{{ request()->attributes->get('csp_nonce') }}">
(()=>{const calendar=document.querySelector('#booking-calendar'),slots=document.querySelector('#booking-slots'),zone=document.querySelector('#booking-timezone'),form=document.querySelector('#booking-form'),start=document.querySelector('#selected-start'),selectedZone=document.querySelector('#selected-timezone'),label=document.querySelector('#month-label');let month=new Date(),selected=null;month.setDate(1);
const monthKey=()=>month.getFullYear()+'-'+String(month.getMonth()+1).padStart(2,'0');const calendarUrl=@json($calendarUrl),availabilityUrl=@json($availabilityUrl),token=@json($token);
async function loadCalendar(){calendar.setAttribute('aria-busy','true');calendar.innerHTML='<p>Carregando calendário…</p>';label.textContent=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(month);try{const url=new URL(calendarUrl,location.origin);url.searchParams.set('month',monthKey());url.searchParams.set('timezone',zone.value);if(token)url.searchParams.set('token',token);const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const data=await response.json();calendar.innerHTML='';Object.entries(data.days).forEach(([date,status])=>{const button=document.createElement('button');button.type='button';button.className='calendar-date status-'+status;button.dataset.date=date;button.disabled=status!=='available';button.textContent=String(Number(date.slice(-2)));button.setAttribute('aria-label',new Intl.DateTimeFormat('pt-BR',{dateStyle:'full',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))+' — '+status.replace('_',' '));button.onclick=()=>selectDate(button,date);calendar.append(button);});}catch(e){calendar.innerHTML='<p class="alert alert-danger" role="alert">Não foi possível carregar o calendário. Tente novamente.</p>';}finally{calendar.setAttribute('aria-busy','false');}}
async function selectDate(button,date){selected=date;calendar.querySelectorAll('.calendar-date').forEach(b=>{b.classList.remove('is-selected');b.setAttribute('aria-selected','false');});button.classList.add('is-selected');button.setAttribute('aria-selected','true');slots.innerHTML='<p>Carregando horários…</p>';form.hidden=true;try{const url=new URL(availabilityUrl,location.origin);url.searchParams.set('date',date);url.searchParams.set('timezone',zone.value);if(token)url.searchParams.set('token',token);const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const data=await response.json();slots.innerHTML=data.slots.length?'':'<p class="empty-state">Nenhum horário disponível.</p>';data.slots.forEach(slot=>{const button=document.createElement('button');button.type='button';button.className='slot-button';button.textContent=slot.label;button.setAttribute('aria-label','Selecionar '+slot.label);button.onclick=()=>{slots.querySelectorAll('.slot-button').forEach(b=>{b.classList.remove('is-selected');b.setAttribute('aria-pressed','false');});button.classList.add('is-selected');button.setAttribute('aria-pressed','true');start.value=slot.start;selectedZone.value=zone.value;form.hidden=false;};slots.append(button);});}catch(e){slots.innerHTML='<p class="alert alert-danger" role="alert">Não foi possível carregar os horários.</p>';}}
document.querySelector('#month-prev').onclick=()=>{month.setMonth(month.getMonth()-1);loadCalendar();};document.querySelector('#month-next').onclick=()=>{month.setMonth(month.getMonth()+1);loadCalendar();};zone.onchange=()=>{selected=null;slots.innerHTML='<p class="empty-state">Selecione uma data disponível.</p>';form.hidden=true;loadCalendar();};loadCalendar();})();
</script>
